import type { TimeGrain } from './model'

/**
 * A QuerySpec is what the report builder produces. It is deliberately small and
 * declarative: it names *what* the user wants (fields, filters, sort) and never
 * *how* to get it. It is JSON-serialisable so reports can be saved, shared, diffed
 * and generated by an assistant without ever producing SQL.
 */

export type FilterOp =
  | 'eq' | 'neq' | 'in' | 'not_in'
  | 'gt' | 'gte' | 'lt' | 'lte' | 'between'
  | 'contains' | 'not_contains' | 'starts_with'
  | 'is_null' | 'not_null'
  | 'relative_date'

/** Relative date presets understood by the compiler. */
export type RelativeDate =
  | 'today' | 'yesterday'
  | 'this_week' | 'last_week'
  | 'this_month' | 'last_month'
  | 'this_quarter' | 'last_quarter'
  | 'this_year' | 'last_year'
  | 'last_7_days' | 'last_30_days' | 'last_90_days' | 'last_12_months'
  | 'year_to_date' | 'quarter_to_date' | 'month_to_date'

export const RELATIVE_DATES: { value: RelativeDate; label: string }[] = [
  { value: 'today', label: 'Today' },
  { value: 'yesterday', label: 'Yesterday' },
  { value: 'this_week', label: 'This week' },
  { value: 'last_week', label: 'Last week' },
  { value: 'this_month', label: 'This month' },
  { value: 'last_month', label: 'Last month' },
  { value: 'this_quarter', label: 'This quarter' },
  { value: 'last_quarter', label: 'Last quarter' },
  { value: 'this_year', label: 'This year' },
  { value: 'last_year', label: 'Last year' },
  { value: 'last_7_days', label: 'Last 7 days' },
  { value: 'last_30_days', label: 'Last 30 days' },
  { value: 'last_90_days', label: 'Last 90 days' },
  { value: 'last_12_months', label: 'Last 12 months' },
  { value: 'month_to_date', label: 'Month to date' },
  { value: 'quarter_to_date', label: 'Quarter to date' },
  { value: 'year_to_date', label: 'Year to date' },
]

export type FilterValue = string | number | boolean | null | Array<string | number | boolean>

export interface Filter {
  /** "table.dimension" (optionally with __grain) or "table.measure" or a derived metric name. */
  field: string
  op: FilterOp
  value?: FilterValue
}

export interface Sort {
  field: string
  dir: 'asc' | 'desc'
}

/** Period-over-period comparison, anchored on the report's date filter. */
export type ComparePeriod = 'previous_period' | 'previous_year'

export const COMPARE_OPTIONS: { value: ComparePeriod; label: string }[] = [
  { value: 'previous_period', label: 'Previous period' },
  { value: 'previous_year', label: 'Same period last year' },
]

export interface QuerySpec {
  /** Dimension refs, e.g. "clients.name", "invoices.issued_at__month". */
  dimensions: string[]
  /** Measure refs ("invoices.total_billed") or derived metric names ("realization"). */
  measures: string[]
  filters: Filter[]
  sorts: Sort[]
  limit?: number
  /**
   * When set, every number is also computed for the comparison period and the
   * report gains "prior", "change" and "change %" columns. Requires a date
   * filter (relative or between) to anchor the period.
   */
  compare?: ComparePeriod
}

export const emptyQuery = (): QuerySpec => ({ dimensions: [], measures: [], filters: [], sorts: [], limit: 500 })

export function grainOf(ref: string): TimeGrain | undefined {
  const i = ref.indexOf('__')
  return i >= 0 ? (ref.slice(i + 2) as TimeGrain) : undefined
}

export function stripGrain(ref: string): string {
  const i = ref.indexOf('__')
  return i >= 0 ? ref.slice(0, i) : ref
}
